"""
Brain 3: Anomaly Cross-Reference Engine.
Triangulates Brain 1 (price deltas) + Brain 2 (forced flows) + founder profile
+ historical anomalies → ranked AnomalyCards. No web calls — pure computation.
"""

import logging
from typing import Optional

from .models import PriceDelta, ForcedFlow, AnomalyCard, FounderProfile, _generate_anomaly_id, _now_iso

logger = logging.getLogger(__name__)


class AnomalyCrossReferencer:
    def __init__(self, historical: Optional[list[AnomalyCard]] = None):
        self.historical = historical or []

    def cross_reference(
        self,
        deltas: list[PriceDelta],
        flows: list[ForcedFlow],
        founder: Optional[FounderProfile] = None,
    ) -> list[AnomalyCard]:
        cards: list[AnomalyCard] = []

        for delta in deltas:
            for flow in flows:
                if self._rule_forced_creates_delta(delta, flow):
                    card = self._build_intersection_card(delta, flow, founder, "RULE_1_FORCED_CREATES_DELTA")
                    cards.append(card)

        for delta in deltas:
            if founder and self._rule_delta_founder_access(delta, founder) > 0.3:
                if not any(c.delta and c.delta.get("product") == delta.product
                           and c.intersection_rule == "RULE_1_FORCED_CREATES_DELTA" for c in cards):
                    card = self._build_delta_card(delta, founder, "RULE_2_DELTA_FOUNDER_ACCESS")
                    cards.append(card)

        for flow in flows:
            if founder and self._rule_flow_founder_expertise(flow, founder) > 0.3:
                if not any(c.flow and c.flow.get("regulation") == flow.regulation
                           and c.intersection_rule == "RULE_1_FORCED_CREATES_DELTA" for c in cards):
                    card = self._build_flow_card(flow, founder, "RULE_3_FLOW_FOUNDER_EXPERTISE")
                    cards.append(card)

        for card in cards:
            hist_boost = self._rule_historical_persistence(card)
            if hist_boost > 0:
                card.anomaly_score = min(1.0, card.anomaly_score + hist_boost)
                card.delta_trend = self._get_historical_trend(card)

        convergence_boost = self._rule_convergence(cards)
        for card in cards:
            key = card.delta.get("product", "") if card.delta else card.flow.get("regulation", "") if card.flow else ""
            if key in convergence_boost:
                card.anomaly_score = min(1.0, card.anomaly_score + convergence_boost[key])

        for card in cards:
            self._score_card(card, founder)
            self._generate_contacts(card)
            self._set_kill_criteria(card)

        cards.sort(key=lambda c: c.final_rank(), reverse=True)
        logger.info(f"Cross-referenced {len(deltas)} deltas × {len(flows)} flows → {len(cards)} anomaly cards")
        return cards

    def _rule_forced_creates_delta(self, delta: PriceDelta, flow: ForcedFlow) -> bool:
        delta_markets = {delta.market_a.lower(), delta.market_b.lower()}
        flow_jurisdiction = flow.jurisdiction.lower()
        geo_match = any(flow_jurisdiction in m or m in flow_jurisdiction for m in delta_markets)
        product_lower = delta.product.lower()
        comply_lower = flow.who_must_comply.lower()
        reg_lower = flow.regulation.lower()
        industry_match = (product_lower in comply_lower or product_lower in reg_lower
                          or comply_lower in product_lower)
        return geo_match or industry_match

    def _rule_delta_founder_access(self, delta: PriceDelta, founder: FounderProfile) -> float:
        score = 0.0
        location_lower = founder.location.lower() if founder.location else ""
        if location_lower:
            if location_lower in delta.market_a.lower() or delta.market_a.lower() in location_lower:
                score += 0.4
        for lang in founder.languages:
            lang_lower = lang.lower()
            market_lang_map = {
                "vietnamese": ["vietnam", "vn"],
                "vi": ["vietnam", "vn"],
                "english": ["us", "uk", "australia", "eu"],
                "en": ["us", "uk", "australia", "eu"],
                "mandarin": ["china", "cn"],
                "chinese": ["china", "cn"],
                "japanese": ["japan", "jp"],
                "ja": ["japan", "jp"],
            }
            market_keys = market_lang_map.get(lang_lower, [])
            for key in market_keys:
                if key in delta.market_a.lower() or key in delta.market_b.lower():
                    score += 0.3
                    break
        if founder.has_industry(delta.product):
            score += 0.3
        return min(1.0, score)

    def _rule_flow_founder_expertise(self, flow: ForcedFlow, founder: FounderProfile) -> float:
        score = 0.0
        flow_text = f"{flow.regulation} {flow.who_must_comply} {flow.provider_gap}".lower()
        flow_words = set(flow_text.split())
        for expertise in founder.domain_expertise:
            exp_words = set(expertise.lower().split())
            if exp_words & flow_words:
                score += 0.4
                break
        for industry in founder.industries:
            ind_words = set(industry.lower().split())
            if ind_words & flow_words:
                score += 0.3
                break
        location_lower = founder.location.lower() if founder.location else ""
        jurisdiction_lower = flow.jurisdiction.lower()
        if location_lower and (jurisdiction_lower in location_lower
                               or any(w in location_lower for w in jurisdiction_lower.split())):
            score += 0.3
        return min(1.0, score)

    def _rule_historical_persistence(self, card: AnomalyCard) -> float:
        if not self.historical:
            return 0.0
        for hist in self.historical:
            if card.delta and hist.delta:
                if (card.delta.get("product") == hist.delta.get("product") and
                    card.delta.get("market_a") == hist.delta.get("market_a")):
                    if hist.delta_trend != "SHRINKING":
                        return 0.15
            if card.flow and hist.flow:
                if card.flow.get("regulation") == hist.flow.get("regulation"):
                    return 0.1
        return 0.0

    def _get_historical_trend(self, card: AnomalyCard) -> str:
        for hist in self.historical:
            if card.delta and hist.delta:
                if card.delta.get("product") == hist.delta.get("product"):
                    return hist.delta_trend
        return "STABLE"

    def _rule_convergence(self, cards: list[AnomalyCard]) -> dict[str, float]:
        signal_counts: dict[str, int] = {}
        for card in cards:
            keys = []
            if card.delta:
                keys.append(card.delta.get("product", ""))
            if card.flow:
                keys.append(card.flow.get("regulation", ""))
            for k in keys:
                if k:
                    signal_counts[k] = signal_counts.get(k, 0) + 1
        return {k: 0.2 for k, v in signal_counts.items() if v >= 3}

    def _score_card(self, card: AnomalyCard, founder: Optional[FounderProfile]):
        if card.anomaly_type == "INTERSECTION":
            card.anomaly_score = max(card.anomaly_score, 0.7)
        elif card.anomaly_type == "PRICE_DELTA":
            card.anomaly_score = max(card.anomaly_score, 0.5)
        elif card.anomaly_type == "FORCED_FLOW":
            card.anomaly_score = max(card.anomaly_score, 0.4)

        if founder:
            fit_scores = []
            if card.delta:
                d = PriceDelta.from_dict(card.delta)
                fit_scores.append(self._rule_delta_founder_access(d, founder))
            if card.flow:
                f = ForcedFlow.from_dict(card.flow)
                fit_scores.append(self._rule_flow_founder_expertise(f, founder))
            card.founder_fit = sum(fit_scores) / len(fit_scores) if fit_scores else 0.1

        if card.flow:
            f = ForcedFlow.from_dict(card.flow)
            card.urgency = f.urgency_score()
        else:
            card.urgency = 0.5

    def _build_intersection_card(self, delta: PriceDelta, flow: ForcedFlow,
                                  founder: Optional[FounderProfile], rule: str) -> AnomalyCard:
        position = self._design_position(delta, flow)
        return AnomalyCard(
            id=_generate_anomaly_id(),
            anomaly_type="INTERSECTION",
            title=f"{delta.product} × {flow.regulation} ({delta.market_a}→{delta.market_b})",
            delta=delta.to_dict(),
            flow=flow.to_dict(),
            intersection_rule=rule,
            position_type=position,
            action="CONNECT" if position == "BROKER" else "CURATE",
            supply_side=f"Producers in {delta.market_a}",
            demand_side=f"Buyers in {delta.market_b} needing {flow.regulation} compliance",
            channel="Direct outreach + trade platforms",
            price_per_unit=delta.price_b,
            cost_per_unit=delta.price_a + delta.bridge_cost,
            anomaly_score=0.7,
            confidence="[T]",
        )

    def _build_delta_card(self, delta: PriceDelta, founder: Optional[FounderProfile],
                           rule: str) -> AnomalyCard:
        return AnomalyCard(
            id=_generate_anomaly_id(),
            anomaly_type="PRICE_DELTA",
            title=f"{delta.product} arbitrage {delta.market_a}→{delta.market_b} ({delta.spread_pct:.0f}%)",
            delta=delta.to_dict(),
            intersection_rule=rule,
            position_type="ARBITRAGE" if delta.spread_pct > 50 else "BROKER",
            action="BUY-SELL" if delta.spread_pct > 50 else "CONNECT",
            supply_side=f"Suppliers in {delta.market_a}",
            demand_side=f"Buyers in {delta.market_b}",
            channel="Trade platforms + direct contacts",
            price_per_unit=delta.price_b,
            cost_per_unit=delta.price_a + delta.bridge_cost,
            anomaly_score=0.5,
            confidence=delta.confidence,
        )

    def _build_flow_card(self, flow: ForcedFlow, founder: Optional[FounderProfile],
                          rule: str) -> AnomalyCard:
        return AnomalyCard(
            id=_generate_anomaly_id(),
            anomaly_type="FORCED_FLOW",
            title=f"{flow.regulation} compliance gap ({flow.jurisdiction})",
            flow=flow.to_dict(),
            intersection_rule=rule,
            position_type=flow.position_opportunity or "INTELLIGENCE",
            action="CURATE",
            supply_side=f"Compliance providers for {flow.regulation}",
            demand_side=f"{flow.who_must_comply} in {flow.jurisdiction}",
            channel="Industry associations + LinkedIn",
            price_per_unit=flow.compliance_cost,
            cost_per_unit=flow.compliance_cost * 0.3,
            anomaly_score=0.4,
            confidence=flow.confidence,
        )

    def _design_position(self, delta: PriceDelta, flow: ForcedFlow) -> str:
        if delta.spread_pct > 50 and flow.provider_gap:
            return "BROKER"
        if flow.provider_gap and "technical" in flow.provider_gap.lower():
            return "INTELLIGENCE"
        if delta.spread_pct > 40:
            return "ARBITRAGE"
        return "BROKER"

    def _generate_contacts(self, card: AnomalyCard):
        if card.contacts:
            return
        product = self._extract_product_name(card)
        contacts = []
        if card.demand_side:
            contacts.append({"side": "demand", "role": "Buyer/importer", "channel": "LinkedIn/email",
                             "script": f"I help source {product} with full compliance. Interested in a sample?"})
            contacts.append({"side": "demand", "role": "Procurement manager", "channel": "Trade platform",
                             "script": f"Verified supply for {product} — competitive pricing."})
            contacts.append({"side": "demand", "role": "Compliance officer", "channel": "Industry event",
                             "script": f"We handle {product} compliance end-to-end."})
        if card.supply_side:
            contacts.append({"side": "supply", "role": "Producer/farmer", "channel": "Local network",
                             "script": f"Looking to buy {product} for export. What's your current price?"})
            contacts.append({"side": "supply", "role": "Cooperative leader", "channel": "Direct visit",
                             "script": f"Exploring partnership for {product} export."})
        card.contacts = contacts[:5]
        if contacts:
            card.script = contacts[0].get("script", "")

    def _extract_product_name(self, card: AnomalyCard) -> str:
        """Extract full product name from card data (not just first word of title)."""
        if card.delta and card.delta.get("product"):
            return card.delta["product"]
        if card.flow and card.flow.get("regulation"):
            return card.flow["regulation"]
        # Fallback: title before first special character
        title = card.title
        for sep in ["×", "x", "(", "|", "—", "-"]:
            if sep in title:
                part = title.split(sep)[0].strip()
                if len(part) > 2:
                    return part
        return title.split()[0] if title else "product"

    def _set_kill_criteria(self, card: AnomalyCard):
        parts = []
        if card.anomaly_type in ("PRICE_DELTA", "INTERSECTION") and card.delta:
            parts.append("Spread drops below 15%")
        if card.anomaly_type in ("FORCED_FLOW", "INTERSECTION") and card.flow:
            parts.append("Regulation repealed or deadline extended >1 year")
        parts.append("No response from 10+ contacts in 14 days")
        card.kill_criteria = " | ".join(parts)
        if card.flow:
            card.deadline = ForcedFlow.from_dict(card.flow).effective_date
        else:
            card.deadline = "30 days from discovery"

"""
Hunt Runner — glue code wiring V5 Brain engines to real DuckDuckGo + Anthropic API.
Creates research_fn (DDG) and llm_fn (Claude Haiku) callbacks for live /hunt execution.
"""

import json
import logging
import os
import time
from pathlib import Path
from typing import Optional

from .models import AnomalyCard, FounderProfile
from .price_delta_engine import PriceDeltaEngine
from .forced_flow_engine import ForcedFlowEngine
from .anomaly_crossref import AnomalyCrossReferencer
from ..store.anomaly_store import AnomalyStore
from ..controller.money_flow_graph import MoneyFlowGraph

logger = logging.getLogger(__name__)

ROOT = Path(__file__).resolve().parents[4]
DEFAULT_PROFILE_PATH = ROOT / "kb" / "profiles" / "phamt-260507.json"
DEFAULT_DB_PATH = ROOT / "data" / "anomalies.duckdb"

_LAST_DDG_TIME = 0.0
_DDG_DELAY_S = 1.6


def _ddg_research(query: str) -> str:
    """Real DuckDuckGo search returning raw snippets + page content."""
    global _LAST_DDG_TIME
    now = time.time()
    if now - _LAST_DDG_TIME < _DDG_DELAY_S:
        time.sleep(_DDG_DELAY_S - (now - _LAST_DDG_TIME))
    _LAST_DDG_TIME = time.time()

    try:
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            try:
                from ddgs import DDGS
            except ImportError:
                from duckduckgo_search import DDGS
            with DDGS() as ddgs:
                results = list(ddgs.text(query, max_results=5))
    except Exception as e:
        logger.warning(f"DDG search failed: {e}")
        return ""

    if not results:
        return ""

    parts = []
    for r in results[:5]:
        title = r.get("title", "")
        body = r.get("body", "")
        href = r.get("href", "")
        parts.append(f"{title}: {body} (source: {href})")

    return "\n".join(parts)


def _create_llm_fn(model: str = "claude-haiku-4-5-20251001") -> callable:
    """Create LLM callback. Tries Anthropic API first, falls back to regex parser."""
    api_available = False
    try:
        import anthropic
        client = anthropic.Anthropic()
        client.models.list(limit=1)
        api_available = True
    except Exception:
        logger.info("Anthropic API unavailable, using regex parser for extraction")

    if api_available:
        import anthropic as _anthropic
        _client = _anthropic.Anthropic()

        def api_llm_fn(prompt: str) -> str:
            try:
                resp = _client.messages.create(
                    model=model,
                    max_tokens=500,
                    messages=[{"role": "user", "content": prompt}],
                )
                text = resp.content[0].text.strip()
                if text.startswith("```"):
                    lines = text.split("\n")
                    text = "\n".join(lines[1:-1]) if len(lines) > 2 else text
                return text
            except Exception as e:
                logger.warning(f"LLM API call failed: {e}, falling back to regex")
                return _regex_parse(prompt)

        return api_llm_fn

    return _regex_parse


def _regex_parse(prompt: str) -> str:
    """Regex-based extraction for price/regulation data from search snippets."""
    import re
    p = prompt.lower()

    if "extract price data" in p or "price" in p and "json" in p:
        return _extract_price_regex(prompt)
    elif "extract regulatory" in p or "regulation" in p and "mandate" in p:
        return _extract_regulation_regex(prompt)
    elif "shipping" in p or "tariff" in p or "bridge" in p:
        return _extract_bridge_cost_regex(prompt)
    elif "compliance" in p or "provider" in p:
        return _extract_provider_regex(prompt)
    elif "entity" in p and "count" in p:
        return _extract_impact_regex(prompt)
    return json.dumps({"product": "unknown", "price": None})


def _extract_price_regex(prompt: str) -> str:
    """Extract price from DDG search snippets using regex.
    Handles: "$3.25/kg", "3.25 to 6.50 USD/kg", "85,400 VND/kg (~3,270 USD/ton)",
    "Rs 315 per kg", "EUR 4.20/kg", etc.
    """
    import re
    text = prompt

    product = ""
    for prod in ["coffee", "pepper", "cashew", "cinnamon", "rubber", "shrimp", "pangasius", "fish"]:
        if prod in text.lower():
            product = prod
            break

    url = ""
    url_match = re.search(r'source:\s*(https?://[^\s\)]+)', text)
    if url_match:
        url = url_match.group(1)

    candidates = []

    # Pattern 1: "X to Y USD/kg" range — take midpoint
    range_matches = re.findall(
        r'([\d,.]+)\s*(?:to|[-–])\s*([\d,.]+)\s*(USD|EUR|usd|eur|\$|€)\s*/?\s*(kg|ton|lb|mt)',
        text, re.IGNORECASE,
    )
    for low_s, high_s, curr, unit in range_matches:
        try:
            low = float(low_s.replace(",", ""))
            high = float(high_s.replace(",", ""))
            price = (low + high) / 2
            usd = _convert_to_usd(price, curr.upper())
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                usd = usd / 1000  # convert to per kg
            candidates.append(("range_usd", usd, url))
        except ValueError:
            pass

    # Pattern 2: parenthesized USD conversion "~3,270 USD/ton"
    paren_matches = re.findall(
        r'[~≈]?\s*([\d,.]+)\s*(USD|usd)\s*/?\s*(kg|ton|mt|tonne)',
        text, re.IGNORECASE,
    )
    for price_s, curr, unit in paren_matches:
        try:
            price = float(price_s.replace(",", ""))
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                price = price / 1000
            candidates.append(("paren_usd", price, url))
        except ValueError:
            pass

    # Pattern 3: "$X.XX/kg" or "$X.XX per kg"
    dollar_matches = re.findall(
        r'\$\s*([\d,.]+)\s*(?:per|/)\s*(kg|kilogram|ton|tonne|lb|mt)',
        text, re.IGNORECASE,
    )
    for price_s, unit in dollar_matches:
        try:
            price = float(price_s.replace(",", ""))
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                price = price / 1000
            candidates.append(("dollar", price, url))
        except ValueError:
            pass

    # Pattern 4: "X.XX USD/kg"
    usd_matches = re.findall(
        r'([\d,.]+)\s*(?:USD|usd)\s*/?\s*(?:per\s+)?(kg|ton|lb|mt)',
        text, re.IGNORECASE,
    )
    for price_s, unit in usd_matches:
        try:
            price = float(price_s.replace(",", ""))
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                price = price / 1000
            candidates.append(("explicit_usd", price, url))
        except ValueError:
            pass

    # Pattern 5: "X.XX EUR/kg"
    eur_matches = re.findall(
        r'([\d,.]+)\s*(?:EUR|eur|€)\s*/?\s*(?:per\s+)?(kg|ton|lb|mt)',
        text, re.IGNORECASE,
    )
    for price_s, unit in eur_matches:
        try:
            price = float(price_s.replace(",", ""))
            usd = price * 1.08
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                usd = usd / 1000
            candidates.append(("eur", usd, url))
        except ValueError:
            pass

    # Pattern 6: VND prices "85,400 VND/kg" — convert to USD
    vnd_matches = re.findall(
        r'([\d,.]+)\s*(?:VND|vnd|dong|đ)\s*/?\s*(?:per\s+)?(kg|ton)',
        text, re.IGNORECASE,
    )
    for price_s, unit in vnd_matches:
        try:
            price = float(price_s.replace(",", ""))
            usd = price * 0.000039
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                usd = usd / 1000
            candidates.append(("vnd", usd, url))
        except ValueError:
            pass

    # Pattern 7: INR "₹315 per kg" or "Rs 315 per kg"
    inr_matches = re.findall(
        r'(?:₹|Rs\.?\s*)([\d,.]+)\s*(?:per\s+)?(kg|ton|lb)',
        text, re.IGNORECASE,
    )
    for price_s, unit in inr_matches:
        try:
            price = float(price_s.replace(",", ""))
            usd = price * 0.012
            candidates.append(("inr", usd, url))
        except ValueError:
            pass

    # Pattern 8: JPY "¥315 per kg" or "JPY 315"
    jpy_matches = re.findall(
        r'(?:¥|JPY|yen)\s*([\d,.]+)\s*(?:per\s+)?(kg|ton|lb)?',
        text, re.IGNORECASE,
    )
    for price_s, *rest in jpy_matches:
        unit = rest[0] if rest and rest[0] else "kg"
        try:
            price = float(price_s.replace(",", ""))
            usd = price * 0.0065
            unit_n = _normalize_unit(unit)
            if unit_n == "ton":
                usd = usd / 1000
            candidates.append(("jpy", usd, url))
        except ValueError:
            pass

    # Filter: price per kg should be in reasonable commodity range ($0.50-$200)
    valid = []
    for source, price_usd_kg, src_url in candidates:
        if 0.50 <= price_usd_kg <= 200:
            valid.append((source, price_usd_kg, src_url))

    if valid:
        # Prefer: paren_usd > explicit_usd > dollar > range_usd > eur > vnd > inr > jpy
        priority = {"paren_usd": 0, "explicit_usd": 1, "dollar": 2,
                     "range_usd": 3, "eur": 4, "vnd": 5, "inr": 6, "jpy": 7}
        valid.sort(key=lambda x: priority.get(x[0], 99))
        _, best_price, best_url = valid[0]
        return json.dumps({
            "product": product or "unknown",
            "price": round(best_price, 2),
            "currency": "USD",
            "unit": "kg",
            "source_url": best_url or url,
        })

    return json.dumps({"product": product or "unknown", "price": None})


def _convert_to_usd(price: float, currency: str) -> float:
    rates = {"USD": 1.0, "$": 1.0, "EUR": 1.08, "€": 1.08,
             "VND": 0.000039, "CNY": 0.14, "JPY": 0.0065,
             "GBP": 1.27, "INR": 0.012}
    return price * rates.get(currency.upper(), 1.0)


def _normalize_unit(unit: str) -> str:
    u = unit.lower().strip()
    if u in ("kg", "kilogram", "kilo"):
        return "kg"
    if u in ("ton", "tonne", "metric ton", "mt"):
        return "ton"
    if u in ("lb", "pound", "lbs"):
        return "lb"
    return "kg"


def _extract_regulation_regex(prompt: str) -> str:
    """Extract regulation info from DDG search snippets.
    Handles: "EU Deforestation Regulation (EUDR)", "Regulation (EU) 2023/1115",
    "Implementing regulation - EU - 2026/148", "Circular 31", etc.
    """
    import re
    text = prompt

    # Specific known regulations first (most valuable)
    known_regs = [
        (r'(EUDR|EU\s+Deforestation\s+Regulation)', "EUDR"),
        (r'(CBAM|Carbon\s+Border\s+Adjustment)', "CBAM"),
        (r'(REACH\s+Regulation)', "EU REACH Regulation"),
        (r'(AI\s+Act)', "EU AI Act"),
        (r'(GDPR)', "GDPR"),
        (r'(FSMA|Food\s+Safety\s+Modernization\s+Act)', "FSMA"),
    ]

    reg_name = None
    for pattern, label in known_regs:
        if re.search(pattern, text, re.IGNORECASE):
            reg_name = label
            break

    if not reg_name:
        # Generic patterns
        reg_patterns = [
            r'(Regulation\s+\(EU\)\s+\d+/\d+)',
            r'(Implementing\s+regulation\s+[-–]\s+EU\s+[-–]\s+\d+/\d+)',
            r'((?:EU|European)\s+[\w\s]{3,30}(?:Regulation|Directive|Act))',
            r'((?:Nghị\s+định|Thông\s+tư|Circular|Decree)\s+\d+)',
            r'((?:US|Federal)\s+[\w\s]{3,30}(?:Act|Rule|Standard))',
        ]
        for pattern in reg_patterns:
            match = re.search(pattern, text, re.IGNORECASE)
            if match:
                reg_name = match.group(1).strip()[:80]
                break

    if not reg_name:
        return json.dumps({"regulation": None})

    # Date extraction — prefer explicit dates, then "from DATE", then year
    effective_date = ""
    date_patterns = [
        r'(?:effective|apply|applies|enter.{0,10}force|deadline)[:\s]+(?:from\s+)?(\d{1,2}\s+\w+\s+\d{4})',
        r'(?:effective|apply|applies|enter.{0,10}force|deadline)[:\s]+(?:from\s+)?(\d{4}[-/]\d{1,2}[-/]\d{1,2})',
        r'(\d{4}[-/]\d{1,2}[-/]\d{1,2})',
        r'(?:from|by|starting)\s+(\d{1,2}\s+\w+\s+\d{4})',
    ]
    for dp in date_patterns:
        dm = re.search(dp, text, re.IGNORECASE)
        if dm:
            raw_date = dm.group(1)
            if re.match(r'\d{4}[-/]', raw_date):
                effective_date = raw_date.replace("/", "-")
            else:
                try:
                    from datetime import datetime
                    for fmt in ("%d %B %Y", "%d %b %Y", "%B %d %Y"):
                        try:
                            dt = datetime.strptime(raw_date.strip(), fmt)
                            effective_date = dt.strftime("%Y-%m-%d")
                            break
                        except ValueError:
                            continue
                except Exception:
                    pass
            if effective_date:
                break
    if not effective_date:
        year_match = re.search(r'(?:effective|deadline|by|from)\s+(\d{4})', text, re.IGNORECASE)
        if year_match:
            effective_date = f"{year_match.group(1)}-01-01"

    # Jurisdiction
    jurisdiction = "global"
    for keyword, jur in [("EU", "EU"), ("European", "EU"), ("US", "US"),
                          ("United States", "US"), ("VN", "VN"), ("Vietnam", "VN"),
                          ("Japan", "Japan"), ("China", "China"), ("UK", "UK")]:
        if keyword.lower() in text.lower():
            jurisdiction = jur
            break

    # Entity count — broader patterns
    entity_count = 0
    entity_patterns = [
        r'([\d,]+)\s*(?:companies|entities|firms|businesses|importers|exporters|operators|manufacturers)',
        r'(?:affects?|impacts?|covers?)\s+(?:about|approximately|around|over|more than)?\s*([\d,]+)\s+(?:\w+\s+)?(?:companies|entities|firms|businesses)',
        r'(?:up to|approximately|around|about|over)\s+([\d,]+)\s+(?:\w+\s+)?(?:companies|entities|businesses)',
    ]
    for ep in entity_patterns:
        em = re.search(ep, text, re.IGNORECASE)
        if em:
            try:
                entity_count = int(em.group(1).replace(",", ""))
                break
            except ValueError:
                pass
    if entity_count == 0:
        # Estimate from market context
        estimates = {"EU": 10000, "US": 15000, "VN": 5000, "Japan": 8000, "global": 20000}
        entity_count = estimates.get(jurisdiction, 5000)

    # Compliance cost
    compliance_cost = 0.0
    cost_patterns = [
        r'\$\s*([\d,.]+)\s*(?:per|/)\s*(?:company|entity|firm|business|operator)',
        r'(?:cost|expense|fee|charge)[:\s]+\$?\s*([\d,.]+)\s*(?:per|/)',
        r'\$\s*([\d,.]+)\s*(?:to|[-–])\s*\$?\s*([\d,.]+)',
        r'([\d,.]+)\s*(?:USD|EUR)\s*(?:per\s+)?(?:company|entity|business)',
    ]
    for cp in cost_patterns:
        cm = re.search(cp, text, re.IGNORECASE)
        if cm:
            try:
                compliance_cost = float(cm.group(1).replace(",", ""))
                break
            except ValueError:
                pass
    if compliance_cost == 0:
        compliance_cost = 5000.0

    # Who must comply
    comply_match = re.search(
        r'(?:must comply|applies to|affects?|required for|mandatory for)\s+(.{10,80}?)(?:\.|,|;|\n)',
        text, re.IGNORECASE,
    )
    who = comply_match.group(1).strip() if comply_match else "affected entities"

    return json.dumps({
        "regulation": reg_name,
        "jurisdiction": jurisdiction,
        "effective_date": effective_date,
        "who_must_comply": who,
        "entity_count_estimate": entity_count,
        "compliance_cost_per_entity": compliance_cost,
        "penalty": "",
        "summary": reg_name,
    })


def _extract_bridge_cost_regex(prompt: str) -> str:
    """Extract shipping/tariff costs from text."""
    import re
    text = prompt

    cost_patterns = [
        r'\$\s*([\d,.]+)\s*/?\s*(?:per\s+)?(kg|ton|container|TEU|20ft|40ft)',
        r'([\d,.]+)\s*(?:USD|usd)\s*/?\s*(?:per\s+)?(kg|ton|container)',
        r'freight[:\s]+\$?\s*([\d,.]+)',
        r'tariff[:\s]+(\d+(?:\.\d+)?)\s*%',
    ]

    for pattern in cost_patterns:
        matches = re.findall(pattern, text, re.IGNORECASE)
        if matches:
            val_str = matches[0][0] if isinstance(matches[0], tuple) else matches[0]
            unit = matches[0][1] if isinstance(matches[0], tuple) and len(matches[0]) > 1 else "kg"
            try:
                amount = float(val_str.replace(",", ""))
                cost_type = "tariff" if "tariff" in text.lower() else "shipping"
                return json.dumps({
                    "cost_type": cost_type,
                    "amount": amount,
                    "currency": "USD",
                    "per_unit": _normalize_unit(unit),
                })
            except ValueError:
                continue

    return json.dumps({"cost_type": "shipping", "amount": None})


def _extract_provider_regex(prompt: str) -> str:
    """Extract compliance provider info from text."""
    import re
    text = prompt

    providers = []
    provider_patterns = [
        r'(?:provider|consultant|service|firm|company)[:\s]+([A-Z][\w\s&]+?)(?:,|\.|;|\n)',
        r'(SGS|Bureau Veritas|Intertek|TUV|Deloitte|EY|KPMG|PwC|McKinsey)',
    ]
    for pattern in provider_patterns:
        matches = re.findall(pattern, text, re.IGNORECASE)
        providers.extend(m.strip() for m in matches[:5])

    gap = ""
    gap_patterns = [
        r'(?:gap|missing|lacking|no|insufficient)[:\s]+(.{10,80}?)(?:\.|;|\n)',
        r'(?:underserved|unmet)[:\s]+(.{10,80}?)(?:\.|;|\n)',
    ]
    for pattern in gap_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            gap = match.group(1).strip()
            break

    if not gap and not providers:
        gap = "no providers identified"

    # Clean up any JSON artifacts in gap string
    gap = gap.replace('"', '').replace('}', '').replace('{', '').strip()

    return json.dumps({"providers": providers[:5], "gap": gap})


def _extract_impact_regex(prompt: str) -> str:
    """Extract entity count and cost per entity."""
    import re
    text = prompt

    entity_count = 0
    for ep in [
        r'([\d,]+)\s*(?:companies|entities|firms|businesses|operators|importers|exporters|manufacturers)',
        r'(?:affects?|impacts?|covers?)\s+(?:about|approximately|over|more than)?\s*([\d,]+)',
        r'(?:up to|approximately|around|about|over)\s+([\d,]+)',
    ]:
        em = re.search(ep, text, re.IGNORECASE)
        if em:
            try:
                entity_count = int(em.group(1).replace(",", ""))
                if entity_count > 10:
                    break
            except ValueError:
                pass

    cost = 0.0
    for cp in [
        r'\$\s*([\d,.]+)\s*(?:per|/)\s*(?:company|entity|firm|business)',
        r'(?:cost|fee|expense)[:\s]+\$?\s*([\d,.]+)',
        r'\$\s*([\d,.]+)',
    ]:
        cm = re.search(cp, text, re.IGNORECASE)
        if cm:
            try:
                val = float(cm.group(1).replace(",", ""))
                if 100 <= val <= 10_000_000:
                    cost = val
                    break
            except ValueError:
                pass

    return json.dumps({"entity_count": entity_count, "cost_per_entity": cost})


def load_founder_profile(path: Optional[str] = None) -> FounderProfile:
    """Load founder profile from JSON file."""
    profile_path = Path(path) if path else DEFAULT_PROFILE_PATH
    if not profile_path.exists():
        logger.warning(f"Profile not found at {profile_path}, using defaults")
        return FounderProfile()

    with open(profile_path, encoding="utf-8") as f:
        data = json.load(f)

    skills = data.get("skills", [])
    languages = []
    lang_set = set()
    for s in skills:
        if s in ("Vietnamese", "English", "Mandarin", "vi", "en"):
            if s not in lang_set:
                lang_set.add(s)
                languages.append(s)
    if "Vietnamese" not in lang_set and "vi" not in lang_set:
        languages.insert(0, "Vietnamese")
    if "English" not in lang_set and "en" not in lang_set:
        languages.append("English")

    industries = []
    mechanisms = data.get("masters_mechanisms", {})
    for desc in mechanisms.values():
        if "trade" in desc.lower():
            industries.append("commodity trading")
        if "coffee" in desc.lower():
            industries.append("coffee export")

    if not industries:
        industries = ["commodity trading", "agriculture"]

    expertise = []
    if "trade_contacts_CN" in skills:
        expertise.append("China trade contacts")
    if "relationship_building" in skills:
        expertise.append("relationship trading")

    return FounderProfile(
        industries=industries,
        languages=languages,
        location=data.get("location", "Vietnam"),
        domain_expertise=expertise,
        capital_range=data.get("capital_range", "$0-1000"),
    )


def run_hunt(
    seed_products: Optional[list[str]] = None,
    markets: Optional[list[str]] = None,
    geographies: Optional[list[str]] = None,
    industries: Optional[list[str]] = None,
    founder_path: Optional[str] = None,
    db_path: Optional[str] = None,
    max_brain1_calls: int = 30,
    max_brain2_calls: int = 30,
    llm_model: str = "claude-haiku-4-5-20251001",
) -> dict:
    """Run the full V5 hunt pipeline with real DuckDuckGo + Claude API.

    Returns dict with keys: cards, deltas, flows, graph_stats, budget.
    """
    founder = load_founder_profile(founder_path)
    llm_fn = _create_llm_fn(llm_model)

    logger.info("=== BRAIN 1: Price Delta Engine ===")
    engine1 = PriceDeltaEngine(
        _ddg_research, llm_fn,
        max_calls=max_brain1_calls, spread_threshold=30.0,
    )
    deltas = engine1.scan(
        seed_products=seed_products,
        markets=markets,
        founder=founder,
    )
    logger.info(f"Brain 1 found {len(deltas)} price deltas "
                f"(used {engine1.budget.calls_used}/{engine1.budget.max_calls})")

    logger.info("=== BRAIN 2: Forced Flow Engine ===")
    engine2 = ForcedFlowEngine(
        _ddg_research, llm_fn,
        max_calls=max_brain2_calls,
    )
    flows = engine2.scan(
        geographies=geographies,
        industries=industries,
        founder=founder,
    )
    logger.info(f"Brain 2 found {len(flows)} forced flows "
                f"(used {engine2.budget.calls_used}/{engine2.budget.max_calls})")

    logger.info("=== GRAPH: Anomaly Overlay ===")
    graph = MoneyFlowGraph()
    graph.add_anomaly_overlay(
        [d.to_dict() for d in deltas],
        [f.to_dict() for f in flows],
    )
    graph_stats = graph.to_dict()["stats"]

    logger.info("=== BRAIN 3: Anomaly Cross-Reference ===")
    store_path = db_path or str(DEFAULT_DB_PATH)
    store = AnomalyStore(store_path)
    historical = store.load_active_cards()

    xref = AnomalyCrossReferencer(historical=historical)
    cards = xref.cross_reference(deltas, flows, founder)

    logger.info("=== PERSIST ===")
    for card in cards:
        store.save_card(card)
        delta_pct = card.delta.get("spread_pct", 0.0) if card.delta else 0.0
        store.record_history(
            card.id, card.anomaly_score,
            card.monthly_income, delta_pct,
        )

    budget_summary = {
        "brain1_used": engine1.budget.calls_used,
        "brain1_max": engine1.budget.max_calls,
        "brain2_used": engine2.budget.calls_used,
        "brain2_max": engine2.budget.max_calls,
        "total_used": engine1.budget.calls_used + engine2.budget.calls_used,
        "total_max": engine1.budget.max_calls + engine2.budget.max_calls,
    }

    store.close()

    return {
        "cards": cards,
        "deltas": deltas,
        "flows": flows,
        "graph_stats": graph_stats,
        "budget": budget_summary,
        "founder": founder,
    }


def format_hunt_output(result: dict) -> str:
    """Format hunt results into readable markdown output."""
    cards = result["cards"]
    deltas = result["deltas"]
    flows = result["flows"]
    budget = result["budget"]

    lines = [
        "# /hunt V5 — Anomaly Intelligence Report",
        "",
        f"## Budget: {budget['total_used']}/{budget['total_max']} web calls",
        f"- Brain 1 (Price Deltas): {budget['brain1_used']}/{budget['brain1_max']}",
        f"- Brain 2 (Forced Flows): {budget['brain2_used']}/{budget['brain2_max']}",
        "",
        f"## Raw Signals: {len(deltas)} price deltas, {len(flows)} forced flows",
        "",
    ]

    if deltas:
        lines.append("### Price Deltas (>30% spread)")
        for d in deltas[:10]:
            lines.append(f"- **{d.product}** {d.market_a}->{d.market_b}: "
                        f"${d.price_a:.2f}->${d.price_b:.2f}/kg "
                        f"(spread {d.spread_pct:.0f}%, "
                        f"net margin {d.net_margin_pct:.0f}%)")
        lines.append("")

    if flows:
        lines.append("### Forced Flows (regulatory mandates)")
        for f in flows[:10]:
            lines.append(f"- **{f.regulation}** ({f.jurisdiction}): "
                        f"{f.entity_count:,} entities × ${f.compliance_cost:,.0f} "
                        f"= ${f.total_forced_spend:,.0f} forced spend")
            if f.provider_gap:
                lines.append(f"  Gap: {f.provider_gap}")
        lines.append("")

    lines.append(f"## Anomaly Cards: {len(cards)} opportunities ranked")
    lines.append("")

    for i, card in enumerate(cards[:10], 1):
        rank = card.final_rank()
        lines.extend([
            f"### #{i}: {card.title}",
            f"- **Type:** {card.anomaly_type} | **Position:** {card.position_type}",
            f"- **Score:** {card.anomaly_score:.2f} | "
            f"**Founder Fit:** {card.founder_fit:.2f} | "
            f"**Urgency:** {card.urgency:.2f} | "
            f"**Rank:** {rank:.4f}",
            f"- **Margin:** ${card.margin_per_unit:.2f}/unit "
            f"→ ${card.monthly_income:.0f}/month ({card.units_per_month} units)",
            f"- **Action:** {card.action}",
            f"- **Kill:** {card.kill_criteria}",
        ])
        if card.deadline:
            lines.append(f"- **Deadline:** {card.deadline}")
        if card.contacts:
            lines.append(f"- **Contacts ({len(card.contacts)}):**")
            for c in card.contacts[:3]:
                lines.append(f"  - {c.get('role', '?')} via {c.get('channel', '?')}: "
                            f"\"{c.get('script', '')}\"")
        lines.append("")

    return "\n".join(lines)

class ForcedFlowEngine:
    def __init__(self, research_fn: Callable, llm_fn: Callable,
                 max_calls: int = 30):
        self.research_fn = research_fn
        self.llm_fn = llm_fn
        self.budget = BudgetTracker(max_calls=max_calls)

    def scan(self, geographies: Optional[list[str]] = None,
             industries: Optional[list[str]] = None,
             founder: Optional[FounderProfile] = None) -> list[ForcedFlow]:
        geos = geographies or DEFAULT_GEOGRAPHIES
        inds = self._resolve_industries(industries, founder)
        logger.info(f"Scanning {len(geos)} geographies × {len(inds)} industries "
                    f"(budget: {self.budget.max_calls})")

        candidates: list[dict] = []
        for geo in geos:
            for ind in inds:
                if not self.budget.can_call():
                    break
                mandate = self._search_mandate(geo, ind)
                if mandate and mandate.get("regulation"):
                    candidates.append(mandate)

        flows: list[ForcedFlow] = []
        for mandate in candidates:
            flow = self._quantify_and_build(mandate)
            if flow:
                flows.append(flow)

        flows.sort(key=lambda f: f.priority_score(), reverse=True)
        logger.info(f"Found {len(flows)} forced flows "
                    f"(used {self.budget.calls_used}/{self.budget.max_calls} calls)")
        return flows

    def _resolve_industries(self, explicit: Optional[list[str]],
                            founder: Optional[FounderProfile]) -> list[str]:
        inds = list(explicit or [])
        if founder:
            inds.extend(founder.industries)
        if not inds:
            inds = DEFAULT_INDUSTRIES[:3]
        seen = set()
        unique = []
        for i in inds:
            il = i.lower().strip()
            if il not in seen:
                seen.add(il)
                unique.append(i.strip())
        return unique

    def _search_mandate(self, geography: str, industry: str) -> Optional[dict]:
        query = REGULATORY_TEMPLATES[0].format(
            industry=industry, geography=geography
        )
        if not self.budget.use():
            return None

        try:
            raw = self.research_fn(query)
        except Exception as e:
            logger.warning(f"Search failed for {industry}/{geography}: {e}")
            return None

        if not raw:
            return None

        try:
            prompt = MANDATE_EXTRACTION_PROMPT.format(text=raw[:3000])
            result = self.llm_fn(prompt)
            if isinstance(result, str):
                result = json.loads(result)
            if result and result.get("regulation"):
                result["_geography"] = geography
                result["_industry"] = industry
            return result
        except Exception as e:
            logger.warning(f"LLM extraction failed for {industry}/{geography}: {e}")
            return None

    def _quantify_and_build(self, mandate: dict) -> Optional[ForcedFlow]:
        entity_count = mandate.get("entity_count_estimate") or 0
        cost_per = mandate.get("compliance_cost_per_entity") or 0

        if entity_count == 0 or cost_per == 0:
            entity_count, cost_per = self._search_impact(mandate)

        providers, gap = self._search_providers(mandate)
        position = self._recommend_position(gap, entity_count, cost_per)
        deadline_days = self._calc_deadline_days(mandate.get("effective_date", ""))

        flow = ForcedFlow(
            regulation=mandate["regulation"],
            jurisdiction=mandate.get("jurisdiction", mandate.get("_geography", "")),
            effective_date=mandate.get("effective_date", ""),
            who_must_comply=mandate.get("who_must_comply", ""),
            entity_count=entity_count,
            compliance_cost=cost_per,

        penalty_for_noncompliance=mandate.get("penalty", ""),
        current_providers=providers,
        provider_gap=gap,
        position_opportunity=position,
        deadline_urgency=deadline_days,
        confidence="[T]",
        sources=[],
    )

    if flow.total_forced_spend > 0 and flow.provider_gap:
        capture_rate = 0.001
        flow.monthly_income_estimate = (flow.total_forced_spend * capture_rate) / 12

    return flow

def _search_impact(self, mandate: dict) -> tuple[int, float]:
    reg = mandate.get("regulation", "")
    query = f"{reg} how many companies affected compliance cost"
    if not self.budget.use():
        return 0, 0

    try:
        raw = self.research_fn(query)
        if not raw:
            return 0, 0
        prompt = f"From this text, extract: entity count (number of companies/entities affected) and compliance cost per entity in USD. Return JSON: {{\"entity_count\": <int>, \"cost_per_entity\": <float>}}\n\nText:\n{raw[:2000]}"
        result = self.llm_fn(prompt)
        if isinstance(result, str):
            result = json.loads(result)
        return (result.get("entity_count") or 0, result.get("cost_per_entity") or 0)
    except Exception:
        return 0, 0

def _search_providers(self, mandate: dict) -> tuple[list[str], str]:
    reg = mandate.get("regulation", "")
    query = f"{reg} compliance provider service consultant"
    if not self.budget.use():
        return [], ""

    try:
        raw = self.research_fn(query)
        if not raw:
            return [], "no providers found"
        prompt = PROVIDER_EXTRACTION_PROMPT.format(text=raw[:2000])
        result = self.llm_fn(prompt)
        if isinstance(result, str):
            result = json.loads(result)
        return (result.get("providers", []), result.get("gap", ""))
    except Exception:
        return [], ""

def _recommend_position(self, gap: str, entity_count: int,
                        cost_per: float) -> str:
    if gap and entity_count > 1000:
        return "BROKER"
    if gap and "technical" in gap.lower():
        return "INTELLIGENCE"
    if entity_count > 5000:
        return "AGGREGATOR"
    return "INTELLIGENCE"

def _calc_deadline_days(self, effective_date: str) -> int:
    if not effective_date:
        return 365
    try:
        from datetime import datetime, timezone
        eff = datetime.strptime(effective_date, "%Y-%m-%d").replace(tzinfo=timezone.utc)
        now = datetime.now(timezone.utc)
        return max(0, (eff - now).days)
    except (ValueError, TypeError):
        return 365

